// Promise polyfill for older environments
(function() {
    function Promise(executor) {
        var self = this;
        self.state = 'pending';
        self.value = undefined;
        self.handlers = [];

        function resolve(value) {
            if (self.state === 'pending') {
                self.state = 'fulfilled';
                self.value = value;
                self.handlers.forEach(handle);
                self.handlers = null;
            }
        }

        function reject(reason) {
            if (self.state === 'pending') {
                self.state = 'rejected';
                self.value = reason;
                self.handlers.forEach(handle);
                self.handlers = null;
            }
        }

        function handle(handler) {
            if (self.state === 'fulfilled') {
                if (typeof handler.onFulfilled === 'function') {
                    try {
                        handler.resolve(handler.onFulfilled(self.value));
                    } catch (e) {
                        handler.reject(e);
                    }
                } else {
                    handler.resolve(self.value);
                }
            } else if (self.state === 'rejected') {
                if (typeof handler.onRejected === 'function') {
                    try {
                        handler.resolve(handler.onRejected(self.value));
                    } catch (e) {
                        handler.reject(e);
                    }
                } else {
                    handler.reject(self.value);
                }
            } else {
                self.handlers.push(handler);
            }
        }

        this.then = function(onFulfilled, onRejected) {
            return new Promise(function(resolve, reject) {
                handle({ onFulfilled: onFulfilled, onRejected: onRejected, resolve: resolve, reject: reject });
            });
        };

        this.catch = function(onRejected) {
            return this.then(null, onRejected);
        };

        try {
            executor(resolve, reject);
        } catch (e) {
            reject(e);
        }
    }

    Promise.resolve = function(value) {
        return new Promise(function(resolve) { resolve(value); });
    };

    Promise.reject = function(reason) {
        return new Promise(function(resolve, reject) { reject(reason); });
    };

    Promise.all = function(promises) {
        return new Promise(function(resolve, reject) {
            var results = [];
            var count = 0;
            promises.forEach(function(p, i) {
                Promise.resolve(p).then(function(val) {
                    results[i] = val;
                    if (++count === promises.length) resolve(results);
                }, reject);
            });
        });
    };

    Promise.race = function(promises) {
        return new Promise(function(resolve, reject) {
            promises.forEach(function(p) {
                Promise.resolve(p).then(resolve, reject);
            });
        });
    };

    window.Promise = Promise;
})();